// index.js  -  WhatsApp auto-reply bot with Meta's official Cloud API
// You need Node.js 18 or higher (comes with fetch built in).
//
// In the terminal, inside an empty folder:
//   npm init -y
//   npm install express
//   node index.js
//
// The three variables below are NOT written here. They're set outside:
//   in Windows PowerShell:  $env:WHATSAPP_TOKEN="EAAG..."
//   in Railway or Render:   the "Variables" / "Environment" tab

const express = require('express');
const app = express();
app.use(express.json());

const TOKEN         = process.env.WHATSAPP_TOKEN;   // system user's permanent token
const PHONE_ID      = process.env.PHONE_NUMBER_ID;  // "Phone number ID", NOT the phone number
const VERIFY_TOKEN  = process.env.VERIFY_TOKEN;     // a phrase you make up, the same one you paste into Meta

// ---------------------------------------------------------------
// 1) Meta calls this ONCE, to check that the URL is yours
// ---------------------------------------------------------------
app.get('/webhook', (req, res) => {
  const mode      = req.query['hub.mode'];
  const token     = req.query['hub.verify_token'];
  const challenge = req.query['hub.challenge'];

  if (mode === 'subscribe' && token === VERIFY_TOKEN) {
    console.log('Meta has verified the webhook. Good.');
    return res.status(200).send(challenge);
  }
  console.error('Verification failed: the verify token does not match.');
  return res.sendStatus(403);
});

// ---------------------------------------------------------------
// 2) Every message a customer sends you lands here
// ---------------------------------------------------------------
app.post('/webhook', async (req, res) => {
  res.sendStatus(200);   // reply NOW. If you're slow, Meta retries and the customer gets everything twice.

  try {
    const value = req.body
      && req.body.entry && req.body.entry[0]
      && req.body.entry[0].changes && req.body.entry[0].changes[0]
      && req.body.entry[0].changes[0].value;

    const msg = value && value.messages && value.messages[0];
    if (!msg) return;    // it wasn't a message: it was a "delivered" or "read" notice

    const from = msg.from; // customer's number, with country code, no +

    if (msg.type !== 'text') {
      await sendText(from, 'For now I only understand text. Type your question.');
      return;
    }

    const reply = await think(msg.text.body);
    await sendText(from, reply);

  } catch (e) {
    console.error('Failed processing the message:', e);
  }
});

// ---------------------------------------------------------------
// 3) Replying within the 24h window: free-form text and free
// ---------------------------------------------------------------
async function sendText(to, text) {
  const url = 'https://graph.facebook.com/v21.0/' + PHONE_ID + '/messages';

  const r = await fetch(url, {
    method: 'POST',
    headers: {
      'Authorization': 'Bearer ' + TOKEN,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      messaging_product: 'whatsapp',
      to: to,
      type: 'text',
      text: { body: text.slice(0, 4000) }   // the real limit is 4096 characters
    })
  });

  if (!r.ok) {
    // This is where you'll see (#131047) if the 24h window has closed on you
    console.error('WhatsApp said no:', r.status, await r.text());
  }
}

// ---------------------------------------------------------------
// 4) What it replies. Swap this for a call to whichever AI you use.
// ---------------------------------------------------------------
async function think(text) {
  const t = text.toLowerCase();
  if (t.includes('hours') || t.includes('open'))    return 'We\'re open 9am to 6pm, Monday to Friday.';
  if (t.includes('price') || t.includes('cost'))    return 'You can see our prices here: https://YOUR-SITE.com/pricing';
  if (t.includes('order'))                          return 'Give me your order number and I\'ll tell you where it stands.';
  return 'Hi, I\'m [YOUR BUSINESS]\'s assistant. Ask me about hours, prices, or orders.';
}

app.listen(3000, () => console.log('Listening on port 3000. Still needs to be exposed to the internet.'));

/* ==========================================================
   STEP 1 - CREATE the template. Done ONCE.
   POST https://graph.facebook.com/v21.0/{YOUR_WABA_ID}/message_templates
   Header: Authorization: Bearer {YOUR_TOKEN}
   ========================================================== */
{
  "name": "order_shipped",
  "language": "en",
  "category": "UTILITY",
  "components": [
    {
      "type": "BODY",
      "text": "Hi {{1}}, your order {{2}} has left our warehouse. Estimated delivery date: {{3}}.",
      "example": {
        "body_text": [["Marta", "A-1042", "Thursday, August 21"]]
      }
    },
    {
      "type": "FOOTER",
      "text": "Reply to this message if you need anything."
    },
    {
      "type": "BUTTONS",
      "buttons": [
        { "type": "URL", "text": "View my order", "url": "https://yoursite.com/orders" }
      ]
    }
  ]
}

/* ==========================================================
   STEP 2 - SEND the already-approved template. This DOES cost money.
   POST https://graph.facebook.com/v21.0/{YOUR_PHONE_NUMBER_ID}/messages
   Header: Authorization: Bearer {YOUR_TOKEN}
   ========================================================== */
{
  "messaging_product": "whatsapp",
  "to": "34600111222",
  "type": "template",
  "template": {
    "name": "order_shipped",
    "language": { "code": "en" },
    "components": [
      {
        "type": "body",
        "parameters": [
          { "type": "text", "text": "Marta" },
          { "type": "text", "text": "A-1042" },
          { "type": "text", "text": "Thursday, August 21" }
        ]
      }
    ]
  }
}

